import {gravityMetres} from '../planet-gravity.mjs';
import * as T from 'three';
import {createFlightEffects} from './moon-flight-effects.mjs';
import {flightPhase} from './moon-dispatch.mjs';
import {vipFlight} from './moon-vip-visit.mjs';
export function createMoonRocket(model,plan){
 const group=new T.Group(),port=plan.placements.find(p=>p.id==='landing'),ground=plan.heightAt(port.x,port.z)+(port.deck??.62);group.position.set(port.x,ground,port.z);let interiorOpen=false,vipDocked=false,lastManifest=null;
 function vessel(asset,scale,title){const base=new T.Group();base.position.y=asset==='RE-072'&&port.asset==='RE-074'?-port.deck:0;group.add(base);const ship=new T.Group();ship.add(model(asset));base.add(ship);ship.userData.inspect={title,kind:title==='USS AURORA'?'Your VIP ship':'Scheduled supply ferry',description:title==='USS AURORA'?'Carries you, your companion and your retinue for the ceremonial base tour.':'Regular supplies, science exports and researcher exchange. Yields the pad to VIP visits.'};const engines=[-1,1].flatMap(x=>[-1,1].map(z=>({x:x*.880263342*scale,y:.596622932*scale,z:z*1.173684456*scale,radius:.273859706*scale})));const effects=createFlightEffects(base,(x,z)=>port.asset==='RE-074'?plan.heightAt(port.x+x,port.z+z)-ground-base.position.y:Math.max(0,plan.heightAt(port.x+x,port.z+z)-ground-base.position.y),engines,{planet:plan.planet,gravity:gravityMetres({type:'moon',planet:plan.planet})});const light=new T.PointLight('#ffd4a0',0,2,2);base.add(light);return {ship,effects,light};}
 const regular=vessel('RE-072',1,'Regular supply ferry'),vip=port.ship==='RE-073'?vessel('RE-073',2,'USS AURORA'):null,cabin=vip?model('RE-076'):null;if(cabin){cabin.visible=false;vip.ship.add(cabin);}
 function setInterior(value){interiorOpen=!!value&&!!cabin&&vipDocked;if(vip){vip.ship.children[0].visible=!interiorOpen;cabin.visible=interiorOpen;vip.ship.userData.interiorOpen=interiorOpen;}}
 function present(v,f,seconds,phaseAt){v.ship.visible=f.phase!=='in-transit';v.ship.position.y=f.altitude;v.ship.userData.activity=f.phase;v.effects.update(seconds,phaseAt);v.light.visible=f.thrust>.01;v.light.intensity=f.thrust*.16;v.light.position.set(0,f.altitude+.4,0);}
 return {group,get interiorAvailable(){return !!cabin;},get interiorOpen(){return interiorOpen;},get interiorDocked(){return vipDocked;},setInterior,update(seconds,manifest){lastManifest=manifest;const f=flightPhase(seconds,manifest);present(regular,f,seconds,t=>flightPhase(t,manifest));regular.ship.userData.liveReadout=()=>`${f.phase} · ${manifest.visits} exchanges · ${manifest.schedule?.holding?'Holding for VIP departure':Math.ceil(Math.max(0,(manifest.schedule?.nextArrival??180)-seconds)/6)+' days to arrival'}`;if(vip){const state={seconds,rocket:manifest},vf=vipFlight(state);vipDocked=vf.phase==='docked';if(!vipDocked)setInterior(false);if(['disembarking','boarding'].includes(manifest.vip?.phase))setInterior(true);present(vip,vf,seconds,t=>vipFlight({seconds:t,rocket:manifest}));vip.ship.userData.liveReadout=()=>`${manifest.vip?.phase??'At home'} · You and your companion · 3-person retinue · 6 seats`; }},dispose(){for(const v of [regular,vip].filter(Boolean)){v.effects.dispose();v.light.dispose();}}};
}
